# Generates test/scipy/test_stats_final_misc.py with scipy 1.18.1.
import numpy as np, scipy.stats as st
x = [2.1, 3.4, 1.9, 5.6, 4.4, 3.8, 2.7, 6.1, 4.9, 3.3]
def L(a): return repr([float(v) for v in np.ravel(a)])
m, v, s = st.bayes_mvs(x, 0.9)
o = ["# Copyright (C) 2026 the Typhon authors",
"# Expected values generated by test/scipy/gen_stats_final_misc.py (scipy 1.18.1).",
"import numpy as np", "import scipy.stats as st", "",
"def close(a, b, rtol: float = 1e-9) -> bool:",
"    return abs(a - b) <= 1e-12 + rtol * abs(b)", "",
f"x = {x!r}", "", "@test", "def test_misc():"]
for n in (1,2,3,4): o.append(f"    assert close(st.kstat(x, {n}), {float(st.kstat(x,n))!r})")
for n in (1,2): o.append(f"    assert close(st.kstatvar(x, {n}), {float(st.kstatvar(x,n))!r})")
o.append(f"    assert close(st.gstd(x), {float(st.gstd(x))!r})")
o.append("    r = st.bayes_mvs(x, 0.9)")
for i,(r) in enumerate((m,v,s)):
    o.append(f"    assert close(r[{i}][0], {float(r[0])!r}, 1e-8)")
    o.append(f"    assert close(r[{i}][1][0], {float(r[1][0])!r}, 1e-8)")
    o.append(f"    assert close(r[{i}][1][1], {float(r[1][1])!r}, 1e-8)")
o.append("    assert st.PermutationMethod(n_resamples=99).n_resamples == 99")
o.append("    assert st.BootstrapMethod().method == 'BCa'")
print("\n".join(o))
